{# ── Company ──────────────────────────────────────────────────────────────────── #}
{% set _company_name = frappe.db.get_single_value("Global Defaults", "default_company") %}
{% set co = frappe.get_doc("Company", _company_name) if _company_name else None %}

{# ── Billing-mode-aware outstanding rows — instabiz.overrides.billing_mode picks
   Sales Order vs Sales Invoice (same basis as ib_ar_aging.py / Customer's own
   outstanding field). Computed server-side via frappe.call() since frappe.conf
   isn't reachable from the sandboxed print-format Jinja context. ────────────────── #}
{% set _stmt = frappe.call("instabiz.overrides.customer.get_outstanding_statement_rows", customer=doc.name) %}
{% set _rows = _stmt.rows %}
{% set _total = _stmt.total %}
{% set _doc_label = _stmt.doc_label %}
{% set _today = frappe.utils.today() %}

{# ── Helpers ──────────────────────────────────────────────────────────────────── #}
{% macro fd(d) %}{% if d %}{{ frappe.utils.formatdate(d, "dd-MMM-yy") }}{% endif %}{% endmacro %}
{% macro fm(v) %}{{ frappe.utils.fmt_money(v|float, precision=2) }}{% endmacro %}

<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, sans-serif; font-size: 11px; color: #000; line-height: 1.5; }
  table { width: 100%; border-collapse: collapse; }
  td, th { vertical-align: top; padding: 4px 6px; }
  strong, b { font-weight: bold; }
  .right { text-align: right; }
  .center { text-align: center; }
  .lbl { color: #444; }
  .small { font-size: 9.5px; }

  .st-tbl { border: 1px solid #000; border-collapse: collapse; margin-top: 10px; }
  .st-tbl th { border: 1px solid #777; background: #f0f0f0; font-weight: bold;
               text-align: center; padding: 5px 6px; font-size: 10.5px; }
  .st-tbl td { border: 1px solid #ccc; padding: 4px 6px; }
  .st-tbl .total-row td { border-top: 1.5px solid #000; border-bottom: none;
                           font-weight: bold; font-size: 12px; }
  img { display: block; }
</style>

<table style="margin-bottom:6px">
  <tr>
    <td style="width:62%; vertical-align:top">
      <table style="border:none; margin-bottom:4px">
        <tr>
          <td style="border:none; padding:0 8px 0 0; width:56px; vertical-align:middle">
            <img src="/files/letterhead.jpeg" style="width:54px; height:auto; max-height:48px; object-fit:contain">
          </td>
          <td style="border:none; padding:0; vertical-align:middle">
            <div style="font-size:14px; font-weight:bold; line-height:1.3">{{ (_company_name or "") | upper }}</div>
          </td>
        </tr>
      </table>
      {% if co and co.gstin %}<div>GSTIN/UIN: <strong>{{ co.gstin }}</strong></div>{% endif %}
      {% if co and co.phone_no %}<div>Contact : <strong>{{ co.phone_no }}</strong></div>{% endif %}
      {% if co and co.email %}<div>E-Mail : <strong>{{ co.email }}</strong></div>{% endif %}
    </td>
    <td style="width:38%; text-align:right; vertical-align:top">
      <div style="font-size:15px; font-weight:bold">Statement of Outstanding Dues</div>
      <div class="lbl" style="margin-top:4px">Statement Date: <strong>{{ fd(_today) }}</strong></div>
      <div class="lbl">As on: <strong>{{ fd(_today) }}</strong></div>
    </td>
  </tr>
</table>

<table style="border:1px solid #000; border-collapse:collapse; margin-bottom:2px">
  <tr>
    <td style="padding:6px 8px">
      <div class="lbl small">Statement For</div>
      <div><strong>{{ doc.customer_name }}</strong></div>
      {% if doc.custom_billing %}<div>{{ doc.custom_billing }}</div>{% endif %}
      {% if doc.custom_bt_city or doc.custom_bt_state %}
      <div>{{ doc.custom_bt_city or "" }}{% if doc.custom_bt_state %}, {{ doc.custom_bt_state }}{% endif %}{% if doc.custom_bt_pincode %}, {{ doc.custom_bt_pincode }}{% endif %}</div>
      {% endif %}
      {% if doc.gstin %}<div>GSTIN/UIN : <strong>{{ doc.gstin }}</strong></div>{% endif %}
      {% if doc.mobile_no %}<div>Mobile : <strong>{{ doc.mobile_no }}</strong></div>{% endif %}
    </td>
  </tr>
</table>

<table class="st-tbl">
  <thead>
    <tr>
      <th style="width:6%">Sl<br>No.</th>
      <th style="width:20%">{{ _doc_label }} No.</th>
      <th style="width:16%">{{ _doc_label }} Date</th>
      <th style="width:16%">Age (days)</th>
      <th style="width:21%">{{ _doc_label }} Amount</th>
      <th style="width:21%">Balance Due</th>
    </tr>
  </thead>
  <tbody>
    {% if _rows %}
      {% for r in _rows %}
      <tr>
        <td class="center">{{ loop.index }}</td>
        <td>{{ r.name }}</td>
        <td class="center">{{ fd(r.doc_date) }}</td>
        <td class="center">{{ frappe.utils.date_diff(_today, r.doc_date) if r.doc_date else "" }}</td>
        <td class="right">{{ fm(r.grand_total) }}</td>
        <td class="right"><strong>{{ fm(r.balance) }}</strong></td>
      </tr>
      {% endfor %}
    {% else %}
      <tr><td colspan="6" class="center lbl" style="padding:14px">No outstanding dues.</td></tr>
    {% endif %}
    {% if _rows %}
    <tr class="total-row">
      <td colspan="5" class="right">Total Outstanding</td>
      <td class="right">₹ {{ fm(_total) }}</td>
    </tr>
    {% endif %}
  </tbody>
</table>

<table style="margin-top:22px; border-top:1px solid #000">
  <tr>
    <td style="width:60%; vertical-align:top; padding-top:6px; font-size:9.5px" class="lbl">
      This is a system-generated statement and does not require a signature.
      For any queries regarding this statement, please contact us{% if co and co.phone_no %} at {{ co.phone_no }}{% endif %}{% if co and co.email %}{% if co.phone_no %} /{% endif %} {{ co.email }}{% endif %}.
    </td>
    <td style="width:40%; text-align:right; vertical-align:top; padding-top:6px">
      <strong>for {{ (_company_name or "") | upper }}</strong>
      <div style="margin-top:24px"><strong>Authorised Signatory</strong></div>
    </td>
  </tr>
</table>
